import { integer, real, sqliteTable, text, uniqueIndex } from 'drizzle-orm/sqlite-core';
const id = () => text('id').primaryKey();
const timestamps = { createdAt: integer('created_at', { mode: 'timestamp_ms' }).notNull(), updatedAt: integer('updated_at', { mode: 'timestamp_ms' }).notNull() };
export const tenants = sqliteTable('tenants', { id: id(), name: text('name').notNull(), slug: text('slug').notNull(), type: text('type').notNull().default('business'), status: text('status').notNull().default('active'), ...timestamps }, t => ({ slugIdx: uniqueIndex('tenants_slug_idx').on(t.slug) }));
export const users = sqliteTable('users', { id: id(), name: text('name').notNull(), email: text('email').notNull(), passwordHash: text('password_hash').notNull(), status: text('status').notNull().default('active'), ...timestamps }, t => ({ emailIdx: uniqueIndex('users_email_idx').on(t.email) }));
export const memberships = sqliteTable('memberships', { id: id(), tenantId: text('tenant_id').notNull().references(() => tenants.id), userId: text('user_id').notNull().references(() => users.id), role: text('role').notNull().default('member'), ...timestamps }, t => ({ uniqueMember: uniqueIndex('memberships_tenant_user_idx').on(t.tenantId, t.userId) }));
export const entities = sqliteTable('entities', { id: id(), tenantId: text('tenant_id').notNull().references(() => tenants.id), name: text('name').notNull(), kind: text('kind').notNull(), taxNumber: text('tax_number'), notes: text('notes'), ...timestamps });
export const phones = sqliteTable('phones', { id: id(), tenantId: text('tenant_id').notNull(), entityId: text('entity_id').notNull().references(() => entities.id), number: text('number').notNull(), isPrimary: integer('is_primary', { mode: 'boolean' }).notNull().default(false), ...timestamps });
export const addresses = sqliteTable('addresses', { id: id(), tenantId: text('tenant_id').notNull(), entityId: text('entity_id').notNull().references(() => entities.id), label: text('label').notNull(), address: text('address').notNull(), isPrimary: integer('is_primary', { mode: 'boolean' }).notNull().default(false), ...timestamps });
export const accounts = sqliteTable('accounts', { id: id(), tenantId: text('tenant_id').notNull().references(() => tenants.id), parentId: text('parent_id'), code: text('code').notNull(), name: text('name').notNull(), type: text('type').notNull(), ...timestamps }, t => ({ accountCode: uniqueIndex('accounts_tenant_code_idx').on(t.tenantId, t.code) }));
export const journalEntries = sqliteTable('journal_entries', { id: id(), tenantId: text('tenant_id').notNull(), reference: text('reference').notNull(), description: text('description').notNull(), postedAt: integer('posted_at', { mode: 'timestamp_ms' }).notNull(), ...timestamps });
export const journalLines = sqliteTable('journal_lines', { id: id(), tenantId: text('tenant_id').notNull(), journalEntryId: text('journal_entry_id').notNull().references(() => journalEntries.id), accountId: text('account_id').notNull().references(() => accounts.id), debit: text('debit').notNull().default('0'), credit: text('credit').notNull().default('0'), ...timestamps });
export const balances = sqliteTable('balances', { id: id(), tenantId: text('tenant_id').notNull(), accountId: text('account_id').notNull(), debit: text('debit').notNull().default('0'), credit: text('credit').notNull().default('0'), ...timestamps }, t => ({ balanceAccount: uniqueIndex('balances_tenant_account_idx').on(t.tenantId, t.accountId) }));
export const documents = sqliteTable('documents', { id: id(), tenantId: text('tenant_id').notNull(), number: text('number').notNull(), type: text('type').notNull(), entityId: text('entity_id'), total: text('total').notNull().default('0'), status: text('status').notNull().default('draft'), ...timestamps });
export const documentLines = sqliteTable('document_lines', { id: id(), tenantId: text('tenant_id').notNull(), documentId: text('document_id').notNull().references(() => documents.id), description: text('description').notNull(), quantity: real('quantity').notNull(), unitPrice: text('unit_price').notNull(), total: text('total').notNull(), ...timestamps });
export const auditLogs = sqliteTable('audit_logs', { id: id(), tenantId: text('tenant_id'), userId: text('user_id'), action: text('action').notNull(), resource: text('resource').notNull(), resourceId: text('resource_id'), metadata: text('metadata'), ...timestamps });
export const settings = sqliteTable('settings', { id: id(), tenantId: text('tenant_id').notNull(), key: text('key').notNull(), value: text('value').notNull(), ...timestamps }, t => ({ settingKey: uniqueIndex('settings_tenant_key_idx').on(t.tenantId, t.key) }));
export const sessions = sqliteTable('sessions', { id: id(), userId: text('user_id').notNull(), tokenHash: text('token_hash').notNull(), expiresAt: integer('expires_at', { mode: 'timestamp_ms' }).notNull(), ...timestamps });
export const tenantCounters = sqliteTable('tenant_counters', { id: id(), tenantId: text('tenant_id').notNull(), key: text('key').notNull(), value: integer('value').notNull().default(0), ...timestamps }, t => ({ counterKey: uniqueIndex('counters_tenant_key_idx').on(t.tenantId, t.key) }));
